    keccak_const::Keccak256::new().update(b"TRANSFER_ROLE").finalize();
const NEW_ADMIN_ROLE: [u8; 32] =
    hex!("879ce0d4bfd332649ca3552efe772a38d64a315eb70ab69689fd309c735946b5");

