/// Extension trait for checking whether a receipt contains an event.
pub trait EventExt<E> {
    /// Return whether the receipt contains `expected`.
    fn emits(&self, expected: E) -> bool;
}

impl<E> EventExt<E> for TransactionReceipt
where
