/// Check whether an Alloy contract error is an EVM panic.
pub trait Panic {
    /// Return whether this error represents `code`.
    fn panicked_with(&self, code: PanicCode) -> bool;
}

impl Panic for alloy::contract::Error {
    fn panicked_with(&self, _code: PanicCode) -> bool {
        let Self::TransportError(error) = self else {
